static int stringValueHubNormalizeRange(stringValueHub *hub) {
    long long start = hub->range_start;
    long long end = hub->range_end;
    size_t strlen = hub->range_len;

    /* SUBSTR treats every descending requested range as empty. */
    if (!strcasecmp(hub->range_client->cmd->fullname, "substr") && start > end) {
        hub->range_empty = 1;
        return 0;
    }

    /* Convert negative indexes */
    if (start < 0 && end < 0 && start > end) {
        hub->range_empty = 1;
        return 0;
    }
    if (start < 0) start = strlen+start;
    if (end < 0) end = strlen+end;
    if (start < 0) start = 0;
    if (end < 0) end = 0;
    if ((unsigned long long)end >= strlen) end = strlen-1;

    /* Precondition: end >= 0 && end < strlen, so the only condition where
     * nothing can be returned is: start > end. */
    if (start > end || strlen == 0) {
        hub->range_empty = 1;
        return 0;
    }
    hub->range_start = start;
    hub->range_end = end;
    hub->range_empty = 0;
    return 1;
}

static int stringValueHubRangeIsEmpty(stringValueHub *hub) {
    if (!hub->range_ready) return 1;
    if (hub->range_empty) return 1;
    if (hub->range_len == 0) return 1;
    return 0;
}

